{
  "name": "opencode-prompt-improvement",
  "version": "0.0.5",
  "description": "OpenCode V2 plugin: cleans prompt text on send without adding requirements. Zero model calls by default.",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ASTRO-CLOU/opencode-prompt-improvement.git"
  },
  "homepage": "https://github.com/ASTRO-CLOU/opencode-prompt-improvement#readme",
  "bugs": {
    "url": "https://github.com/ASTRO-CLOU/opencode-prompt-improvement/issues"
  },
  "type": "module",
  "exports": {
    ".": "./index.ts",
    "./rpc": "./src/rpc.ts",
    "./tui": "./src/tui.ts"
  },
  "files": [
    "index.ts",
    "src",
    "LICENSE",
    "README*.md"
  ],
  "scripts": {
    "test": "node --test",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-v2",
    "prompt",
    "hook"
  ],
  "license": "MIT",
  "dependencies": {
    "@opencode/plugin": "^2.3.2"
  },
  "devDependencies": {
    "@types/node": "^24.0.0",
    "typescript": "^5.9.0"
  }
}

import { Plugin } from "@opencode/plugin"
import { createToggle } from "./src/control.ts"
import {
  formatModelList,
  listAvailableModels,
  parseModelArgument,
  type AvailableModel,
} from "./src/model.ts"
import { remapMentions, type MentionCarrier } from "./src/mentions.ts"
import { resolveOptions } from "./src/options.ts"
import { refinePrompt } from "./src/refine.ts"
import { RefineRpc, TUI_LOADED_KEY, type NoticeVariant } from "./src/rpc.ts"
import { createSettings } from "./src/settings.ts"
import type { GenerateTextFn, Mention, ModelRef } from "./src/types.ts"

interface GenerateApi {
  text(
    input: { model: ModelRef; prompt: string },
    options?: { signal?: AbortSignal },
  ): Promise<unknown>
}

function applyMentions(
  attachments: MentionCarrier[],
  mapped: (Mention | undefined)[] | undefined,
): void {
  if (mapped === undefined) return

  for (let index = 0; index < attachments.length; index++) {
    const mention = mapped[index]
    if (mention !== undefined && attachments[index] !== undefined) {
      attachments[index].mention = mention
    }
  }
}

export default Plugin.define({
  id: "opencode-prompt-improvement",

  async setup(ctx) {
    const options = resolveOptions(ctx.options)
    const toggle = createToggle(ctx.storage)
    const settings = createSettings(ctx.storage)
    const generateApi = (ctx.experimental as unknown as { generate: GenerateApi }).generate
    const generate: GenerateTextFn = (input, requestOptions) =>
      generateApi.text(input, requestOptions)
    const effectiveOptions = () => settings.effectiveOptions(options)
    const rpc = await ctx.rpc.register(RefineRpc, {
    markLoaded: async () => {
      await ctx.storage.set(TUI_LOADED_KEY, true)
      return { ok: true }
    },
    isLoaded: async () => ({ ok: (await ctx.storage.get(TUI_LOADED_KEY)) === true }),
  })

    await ctx.session.hook("prompt", async (event) => {
      if ((await toggle.isEnabled()) === false) return

      const original = event.prompt.text
      const files = event.prompt.files ?? []
      const agents = event.prompt.agents ?? []
      const skills = event.prompt.skills ?? []
      const attachments: MentionCarrier[] = [...files, ...agents, ...skills]
      const hasMentions = attachments.some((attachment) => attachment.mention !== undefined)

      const refinement = await refinePrompt(
        original,
        await effectiveOptions(),
        generate,
        !hasMentions,
      )
      if (refinement === undefined || refinement.text === original) return

      const mappedFiles = remapMentions(files, refinement)
      const mappedAgents = remapMentions(agents, refinement)
      const mappedSkills = remapMentions(skills, refinement)
      if (!mappedFiles || !mappedAgents || !mappedSkills) return

      applyMentions(files, mappedFiles)
      applyMentions(agents, mappedAgents)
      applyMentions(skills, mappedSkills)
      event.prompt.text = refinement.text
    })

    const notify = async (
      sessionID: string,
      text: string,
      variant: NoticeVariant = "info",
    ) => {
      await rpc.events.emit("notice", { text, variant, sessionID })
    }

    const switchTo = async (sessionID: string, enabled: boolean) => {
      await toggle.setEnabled(enabled)
      await notify(
        sessionID,
        enabled
          ? "Prompt refinement is on."
          : "Prompt refinement is off. Prompts are sent exactly as typed.",
        enabled ? "success" : "warning",
      )
    }

    const reportStatus = async (sessionID: string) => {
      const enabled = await toggle.isEnabled()
      const effective = await effectiveOptions()
      const model = effective.model
        ? `${effective.model.providerID}/${effective.model.id}`
        : "none"
      await notify(
        sessionID,
        `Prompt refinement is ${enabled ? "on" : "off"}. Mode: ${effective.mode}. Model: ${model}.`,
      )
    }

    const reportModelStatus = async (sessionID: string) => {
      const effective = await effectiveOptions()
      const model = effective.model
        ? `${effective.model.providerID}/${effective.model.id}`
        : "not set"
      await notify(sessionID, `Mode: ${effective.mode}. Model: ${model}.`)
    }

    const loadModels = async (sessionID: string): Promise<AvailableModel[] | undefined> => {
      try {
        return await listAvailableModels(ctx.model)
      } catch {
        await notify(sessionID, "Could not load the model list.", "error")
        return undefined
      }
    }

    await ctx.command.transform((editor) => {
      editor.add({
        name: "refine-off",
        description: "Send prompts exactly as typed, without refinement",
        execute: ({ sessionID }) => switchTo(sessionID, false),
      })
      editor.add({
        name: "refine-on",
        description: "Enable prompt refinement",
        execute: ({ sessionID }) => switchTo(sessionID, true),
      })
      editor.add({
        name: "refine-status",
        description: "Show refinement state, mode and model",
        execute: ({ sessionID }) => reportStatus(sessionID),
      })
      editor.add({
        name: "refine",
        description: "Control prompt refinement: on, off or status",
        execute: ({ sessionID, prompt }) => {
          const argument = (prompt.text ?? "").trim().toLowerCase()
          if (argument === "off" || argument === "disable") return switchTo(sessionID, false)
          if (argument === "on" || argument === "enable") return switchTo(sessionID, true)
          return reportStatus(sessionID)
        },
      })
      editor.add({
        name: "refine-model",
        description: "Set the model used for prompt refinement",
        execute: async ({ sessionID, prompt }) => {
          const argument = (prompt.text ?? "").trim()
          const keyword = argument.toLowerCase()

          if (argument.length === 0 || keyword === "status") return reportModelStatus(sessionID)
          if (keyword === "off") {
            await settings.setMode("deterministic")
            await notify(sessionID, "LLM pass is off. Deterministic cleanup only.")
            return
          }
          if (keyword === "clear") {
            await settings.clear()
            await notify(sessionID, "Model settings cleared. Plugin options are used again.")
            return
          }

          const models = await loadModels(sessionID)
          if (models === undefined) return

          const model = parseModelArgument(argument, models)
          if (model === undefined) {
            await notify(
              sessionID,
              "Model not found. Use /refine-models to list models.",
              "warning",
            )
            return
          }

          await settings.setModel(model)
          await settings.setMode("llm")
          await toggle.setEnabled(true)
          await notify(sessionID, `Prompt refinement now uses ${model.providerID}/${model.id}.`)
        },
      })
      editor.add({
        name: "refine-models",
        description: "List models available for prompt refinement",
        execute: async ({ sessionID, prompt }) => {
          const models = await loadModels(sessionID)
          if (models === undefined) return
          const filter = (prompt.text ?? "").trim()
          await notify(sessionID, formatModelList(models, filter))
        },
      })
    })
  },
})
